class Solution {
public:
    bool btreeGameWinningMove(TreeNode* root, int n, int x) {
        int left_cnt = 0, right_cnt = 0;

        auto count_nodes = [&](auto& self, TreeNode* node) -> int {
            if (!node) return 0;
            int l = self(self, node->left);
            int r = self(self, node->right);
            if (node->val == x) {
                left_cnt = l;
                right_cnt = r;
            }
            return 1 + l + r;
        };

        count_nodes(count_nodes, root);
        int parent_cnt = n - (left_cnt + right_cnt + 1);
        return max({left_cnt, right_cnt, parent_cnt}) > n / 2;
    }
};

class Solution {
    int leftCnt = 0;
    int rightCnt = 0;

    int countNodes(TreeNode node, int x) {
        if (node == null) return 0;
        int l = countNodes(node.left, x);
        int r = countNodes(node.right, x);
        if (node.val == x) {
            leftCnt = l;
            rightCnt = r;
        }
        return 1 + l + r;
    }

    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        countNodes(root, x);
        int parentCnt = n - (leftCnt + rightCnt + 1);
        return Math.max(leftCnt, Math.max(rightCnt, parentCnt)) > n / 2;
    }
}

var btreeGameWinningMove = function(root, n, x) {
    let leftCnt = 0, rightCnt = 0;

    const countNodes = (node) => {
        if (!node) return 0;
        const l = countNodes(node.left);
        const r = countNodes(node.right);
        if (node.val === x) {
